1	package world
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"reflect"
8		"strings"
9		"testing"
10	)
11	
12	// rewriteRecordDuplicate 对记录文件做一次原始文本替换（在同一对象内注入
13	// 同名字段），并按替换后解码（同名字段后者覆盖前者）的内容重算校验和写回，
14	// 模拟“同一对象内出现重复名称、解码后的世界合法且校验和匹配”的损坏记录。
15	func rewriteRecordDuplicate(t *testing.T, a *Archive, id RecordID, from, to string) {
16		t.Helper()
17		path := recordPath(a.dir, id)
18		raw, err := os.ReadFile(path)
19		if err != nil {
20			t.Fatal(err)
21		}
22		var env envelope
23		if err := json.Unmarshal(raw, &env); err != nil {
24			t.Fatal(err)
25		}
26		oldSum := env.Checksum
27		if !strings.Contains(string(raw), from) {
28			t.Fatalf("记录 %s 中找不到待替换文本 %q", id, from)
29		}
30		corrupted := strings.Replace(string(raw), from, to, 1)
31		// encoding/json 对同名字段静默采用后一个值，解析仍然成功；按解码结果
32		// 重算校验和，使重复名称在校验和下被掩盖。
33		var cenv envelope
34		if err := json.Unmarshal([]byte(corrupted), &cenv); err != nil {
35			t.Fatalf("测试前提：注入重复名称后的记录应仍可被 encoding/json 解析: %v", err)
36		}
37		corrupted = strings.Replace(corrupted, oldSum, computeChecksum(&cenv), 1)
38		if err := os.WriteFile(path, []byte(corrupted), 0o600); err != nil {
39			t.Fatal(err)
40		}
41	}
42	
43	// assertDuplicateNameCorrupt 断言 err 是保留了被拒绝记录标识、且说明名称
44	// 重复的 *CorruptError，而不是版本拒绝或其它错误。
45	func assertDuplicateNameCorrupt(t *testing.T, err error, id RecordID) {
46		t.Helper()
47		ce, ok := err.(*CorruptError)
48		if !ok {
49			t.Fatalf("应为 *CorruptError，得到 %T: %v", err, err)
50		}
51		if ce.Record != id {
52			t.Fatalf("CorruptError 应保留被拒绝的记录标识 %s，得到 %q", id, ce.Record)
53		}
54		if !strings.Contains(ce.Error(), "重复") {
55			t.Fatalf("错误应说明名称重复: %v", ce)
56		}
57		if errors.As(err, new(*VersionRejectedError)) {
58			t.Fatalf("名称重复不应报成版本拒绝: %v", err)
59		}
60	}
61	
62	// TestLatestAndRecordDuplicateNameCorrupt 同一 JSON 对象内出现同名字段时，
63	// 无论两个值是否相同、采用后一个值后的世界是否合法、校验和是否匹配，Latest
64	// 与 Record 都必须把整条记录视为损坏，返回保留记录标识并说明名称重复的
65	// *CorruptError；即使规则版本不在可接受集合内也先报损坏。读取保持只读，
66	// 不修补这份记录，也不切换槽当前记录。
67	func TestLatestAndRecordDuplicateNameCorrupt(t *testing.T) {
68		cases := []struct {
69			name string
70			from string
71			to   string
72		}{
73			// 记录顶层字段，两个值相同也算重复。
74			{"顶层同值", `"format": 1,`, `"format": 1, "format": 1,`},
75			// 记录顶层字段，前者是矛盾值、后者写回合法值。
76			{"顶层异值", `"slotFirst": false,`, `"slotFirst": true, "slotFirst": false,`},
77			// 先写负时间片，再用同名字段写回合法时间片。
78			{"负时间片写回", `"Time": 1,`, `"Time": -5, "Time": 1,`},
79			// 世界规则中的字段。
80			{"规则版本", `"Version": "v1",`, `"Version": "v9", "Version": "v1",`},
81			// 角色对象中的字段。
82			{"角色标识", `"ID": "hero",`, `"ID": "villain", "ID": "hero",`},
83			// 物品条目中的字段。
84			{"物品名称", `"Item": "gold",`, `"Item": "key", "Item": "gold",`},
85			{"物品数量", `"Count": 1`, `"Count": -9, "Count": 1`},
86			// 名称到数值的携带上限对象。
87			{"携带上限", `"hero": 5,`, `"hero": 99, "hero": 5,`},
88			// 直接写出的名称与表示同一名称的 Unicode 转义（\u0049D）同为 "ID"。
89			{"Unicode转义同名", `"ID": "hero",`, `"\u0049D": "hero", "ID": "hero",`},
90			// 转义写在前：先以转义形式给出同一名称，再直接写出。
91			{"Unicode转义同名在前", `"ID": "hero",`, `"ID": "hero", "\u0049D": "hero",`},
92		}
93		for _, tc := range cases {
94			t.Run(tc.name, func(t *testing.T) {
95				a, _ := newTestArchive(t)
96				ids := saveN(t, a, "s", 1) // r1(time 1) r0(time 0)
97				rewriteRecordDuplicate(t, a, ids[0], tc.from, tc.to)
98				before := recordFileBytes(t, a, ids[0])
99	
100				_, err := a.Latest("s", []string{"v1"})
101				assertDuplicateNameCorrupt(t, err, ids[0])
102	
103				_, err = a.Record("s", ids[0], []string{"v1"})
104				assertDuplicateNameCorrupt(t, err, ids[0])
105	
106				// 版本不被接受时同样报损坏，不报版本拒绝。
107				_, err = a.Latest("s", []string{"other"})
108				assertDuplicateNameCorrupt(t, err, ids[0])
109	
110				// 记录没有被悄悄修补或删除，槽指向不变。
111				if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
112					t.Fatal("读取改写了名称重复的记录")
113				}
114				if p, err := a.readSlotPointerLocked("s"); err != nil || p.Latest != ids[0] {
115					t.Fatalf("槽指向不应改变: %+v err=%v", p, err)
116				}
117	
118				// 本槽完好的历史记录不受影响，仍可正常读取。
119				if _, err := a.Record("s", ids[1], []string{"v1"}); err != nil {
120					t.Fatalf("完好的历史记录应可读: %v", err)
121				}
122			})
123		}
124	}
125	
126	// TestHistorySkipsDuplicateNameRecords 带历史索引的槽中，含重复名称的记录
127	// 在浏览时只被略过，其余完好记录仍按保存生效次序列出；恢复读取与恢复预览
128	// 跳过它，选择本槽最近一份完好且版本可接受的记录，全部不可用时返回
129	// ErrUnrecoverable。浏览、读取与预览都不修补、删除或切换任何内容。
130	func TestHistorySkipsDuplicateNameRecords(t *testing.T) {
131		a, _ := newTestArchive(t)
132		ids := saveN(t, a, "s", 2) // r2(time 2) r1(time 1) r0(time 0)
133		rewriteRecordDuplicate(t, a, ids[0], `"Time": 2,`, `"Time": -1, "Time": 2,`)
134		before := recordFileBytes(t, a, ids[0])
135	
136		// 浏览略过名称重复的最新记录，其余按保存生效次序列出。
137		infos, err := a.History("s")
138		if err != nil {
139			t.Fatalf("History: %v", err)
140		}
141		if len(infos) != 2 || infos[0].ID != ids[1] || infos[1].ID != ids[2] {
142			t.Fatalf("名称重复的记录应被略过，其余按次序列出: %+v", infos)
143		}
144	
145		// 恢复读取与恢复预览选中最近一份完好且版本可接受的记录。
146		rec, err := a.RecoverLatest("s", []string{"v1"})
147		if err != nil {
148			t.Fatalf("RecoverLatest: %v", err)
149		}
150		if rec.ID != ids[1] || rec.State.Time != 1 {
151			t.Fatalf("应恢复 %s（时间片 1），得到 %s（时间片 %d）", ids[1], rec.ID, rec.State.Time)
152		}
153		pv, err := a.PreviewRecovery("s", []string{"v1"})
154		if err != nil {
155			t.Fatalf("PreviewRecovery: %v", err)
156		}
157		if pv.Current != ids[0] || pv.Source != ids[1] {
158			t.Fatalf("预览应为 current=%s source=%s，得到 current=%s source=%s",
159				ids[0], ids[1], pv.Current, pv.Source)
160		}
161	
162		// 全部记录都含重复名称时，恢复与预览返回 ErrUnrecoverable。
163		rewriteRecordDuplicate(t, a, ids[1], `"Time": 1,`, `"Time": -1, "Time": 1,`)
164		rewriteRecordDuplicate(t, a, ids[2], `"Time": 0,`, `"Time": -1, "Time": 0,`)
165		if _, err := a.RecoverLatest("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
166			t.Fatalf("全部损坏应不可恢复，得到 %T: %v", err, err)
167		}
168		if _, err := a.PreviewRecovery("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
169			t.Fatalf("预览同样应不可恢复，得到 %T: %v", err, err)
170		}
171		if infos, err := a.History("s"); err != nil || len(infos) != 0 {
172			t.Fatalf("全部损坏时历史应为成功的空列表: %+v err=%v", infos, err)
173		}
174	
175		// 全程只读：受损文件未被修补或删除，槽当前指向不变。
176		if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
177			t.Fatal("浏览/恢复改写了名称重复的记录")
178		}
179		if p, err := a.readSlotPointerLocked("s"); err != nil || p.Latest != ids[0] {
180			t.Fatalf("槽指向不应改变: %+v err=%v", p, err)
181		}
182	}
183	
184	// TestDuplicateNameLegacyPointerHistory 旧格式裸指针沿父链重建历史时，含
185	// 重复名称的记录同样校验不过：重建停在那里，无法确认归属的更老记录不进入
186	// 恢复候选。
187	func TestDuplicateNameLegacyPointerHistory(t *testing.T) {
188		a, dir := newTestArchive(t)
189		ids := saveN(t, a, "s", 3) // r3 r2 r1 r0
190		rewriteRecordDuplicate(t, a, ids[2], `"Time": 1,`, `"Time": -1, "Time": 1,`)
191		writeLegacyPointer(t, a, "s", ids[0])
192	
193		a2, err := Open(dir)
194		if err != nil {
195			t.Fatal(err)
196		}
197		// 最新与次新完好：恢复仍命中最新记录。
198		rec, err := a2.RecoverLatest("s", []string{"v1"})
199		if err != nil {
200			t.Fatalf("名称重复记录之前的完好记录应可恢复: %v", err)
201		}
202		if rec.ID != ids[0] {
203			t.Fatalf("应恢复最新记录 %s，得到 %s", ids[0], rec.ID)
204		}
205	
206		// 最新与次新也损坏后，链在名称重复的记录处断裂，首存记录无法确认归属。
207		corruptChecksum(t, dir, ids[0])
208		corruptChecksum(t, dir, ids[1])
209		if _, err := a2.RecoverLatest("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
210			t.Fatalf("断裂处更老的记录不应进入候选，得到 %T: %v", err, err)
211		}
212	}
213	
214	// TestDistinctObjectsSameNameStillReadable 不同对象各自使用相同名称是正常
215	// 内容：两个角色各自有标识与物品、两个物品条目各自有名称与数量字段，不能
216	// 被误判为重复。字符串值中的文字和标点（包括看起来像对象内容的名称）不算
217	// 对象名称。合法中文名称及其 Unicode 转义写法、只改变缩进或字段排列但内容
218	// 未变的记录都照常可读。
219	func TestDistinctObjectsSameNameStillReadable(t *testing.T) {
220		a, _ := newTestArchive(t)
221		w, err := NewWorld(InitialData{
222			Seed: 7,
223			Rules: Rules{
224				Version:     "v1",
225				Locations:   []string{"大厅", "院子"},
226				Edges:       []Edge{{From: "大厅", To: "院子"}},
227				ItemKinds:   []string{"金币", "钥匙"},
228				CarryLimits: map[string]int{"英雄": 5},
229			},
230			Characters: []Character{
231				{ID: "英雄", Location: "大厅", Items: []CharacterItem{
232					{Item: "金币", Count: 1},
233					{Item: "钥匙", Count: 2},
234				}},
235				// 字符串值中的标点与文字不算对象名称。
236				{ID: `{"ID": 1, "Count": 2}`, Location: "院子"},
237				{ID: "Count", Location: "院子"},
238			},
239		})
240		if err != nil {
241			t.Fatalf("NewWorld: %v", err)
242		}
243		want := w.Snapshot()
244		info, err := a.Save("s", w)
245		if err != nil {
246			t.Fatalf("Save: %v", err)
247		}
248	
249		rec, err := a.Latest("s", []string{"v1"})
250		if err != nil {
251			t.Fatalf("不同对象各自使用相同名称的记录应可读: %v", err)
252		}
253		if !reflect.DeepEqual(rec.State, want) {
254			t.Fatalf("读回状态与保存前不一致:\n got %+v\nwant %+v", rec.State, want)
255		}
256	
257		// 把文件中的中文名称改写为 Unicode 转义写法：解析内容不变，也不与
258		// 直接写出的同名字符串值构成重复，记录应照常可读。
259		path := recordPath(a.dir, info.ID)
260		raw, err := os.ReadFile(path)
261		if err != nil {
262			t.Fatal(err)
263		}
264		s := strings.ReplaceAll(string(raw), "大厅", `\u5927\u5385`)
265		s = strings.ReplaceAll(s, "英雄", `\u82f1\u96c4`)
266		if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
267			t.Fatal(err)
268		}
269		rec, err = a.Latest("s", []string{"v1"})
270		if err != nil {
271			t.Fatalf("合法转义写法的记录应可读: %v", err)
272		}
273		if !reflect.DeepEqual(rec.State, want) {
274			t.Fatalf("读回状态与保存前不一致:\n got %+v\nwant %+v", rec.State, want)
275		}
276	
277		// 只改变缩进与字段排列（经 map 重新序列化）但内容未变的记录仍可读。
278		var m map[string]any
279		if err := json.Unmarshal([]byte(s), &m); err != nil {
280			t.Fatal(err)
281		}
282		flat, err := json.Marshal(m)
283		if err != nil {
284			t.Fatal(err)
285		}
286		if err := os.WriteFile(path, flat, 0o600); err != nil {
287			t.Fatal(err)
288		}
289		rec, err = a.Latest("s", []string{"v1"})
290		if err != nil {
291			t.Fatalf("仅改变格式的记录应可读: %v", err)
292		}
293		if !reflect.DeepEqual(rec.State, want) {
294			t.Fatalf("读回状态与保存前不一致:\n got %+v\nwant %+v", rec.State, want)
295		}
296	}
