		t.Fatal("ID/id 应判为重复")
	} else {
		t.Logf("ID/id => %v", err)
	}
	// 不同对象同名字段 OK
	doc4 := `{"state":{"Characters":[{"ID":"a"},{"ID":"b"}]}}`
	if err := checkDuplicateNames([]byte(doc4)); err != nil {
		t.Fatalf("不同对象同名字段不应重复: %v", err)
	}
	// Unicode 转义 + 大小写：time vs Time（t = 't'）
	doc5 := `{"state":{"Time":1,"time":2}}`
	if err := checkDuplicateNames([]byte(doc5)); err == nil {
