// rewriteRecordText 对记录文件做一次原始文本替换，并按替换后实际解码出的
// 内容重算校验和写回。它既可以注入重复字段（后一个值遮住前一个值后校验和
// 仍匹配），也可以只把唯一字段改写成另一种大小写写法（解码内容不变）。
func rewriteRecordText(t *testing.T, a *Archive, id RecordID, from, to string) {
	t.Helper()
	path := recordPath(a.dir, id)
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(raw), from) {
		t.Fatalf("记录 %s 中找不到待替换文本 %q", id, from)
	}
	var env envelope
	if err := json.Unmarshal(raw, &env); err != nil {
		t.Fatal(err)
	}
	rewritten := strings.Replace(string(raw), from, to, 1)
	var decoded envelope
	if err := json.Unmarshal([]byte(rewritten), &decoded); err != nil {
		t.Fatalf("测试前提：替换后的记录应仍能被 encoding/json 解析: %v", err)
	}
	rewritten = strings.Replace(rewritten, env.Checksum, computeChecksum(&decoded), 1)
	if err := os.WriteFile(path, []byte(rewritten), 0o600); err != nil {
		t.Fatal(err)
	}
}

