			_, err = a.Latest("s", []string{"other"})
			assertDuplicateNameCorrupt(t, err, ids[0])

			// 只读：文件不被修补，槽指向不变；本槽更早的完好记录仍可读。
			if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
				t.Fatal("读取改写了含重复字段的记录")
