package world

import (
	"encoding/json"
	"errors"
	"os"
	"reflect"
	"strings"
	"testing"
)

// rewriteRecordText 对记录文件做一次原始文本替换，并按替换后实际解码出的
// 内容重算校验和写回。它既可以注入重复字段（后一个值遮住前一个值后校验和
// 仍匹配），也可以只把唯一字段改写成另一种大小写写法（解码内容不变）。
func rewriteRecordText(t *testing.T, a *Archive, id RecordID, from, to string) {
	t.Helper()
	path := recordPath(a.dir, id)
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(raw), from) {
		t.Fatalf("记录 %s 中找不到待替换文本 %q", id, from)
	}
	var env envelope
	if err := json.Unmarshal(raw, &env); err != nil {
		t.Fatal(err)
	}
	rewritten := strings.Replace(string(raw), from, to, 1)
	var decoded envelope
	if err := json.Unmarshal([]byte(rewritten), &decoded); err != nil {
		t.Fatalf("测试前提：替换后的记录应仍能被 encoding/json 解析: %v", err)
	}
	rewritten = strings.Replace(rewritten, env.Checksum, computeChecksum(&decoded), 1)
	if err := os.WriteFile(path, []byte(rewritten), 0o600); err != nil {
		t.Fatal(err)
	}
}

// TestCaseVariantDuplicateFixedFieldCorrupt 同一对象内两个名称只要会被
// encoding/json 读取为同一个固定字段（仅大小写或 Unicode 转义写法不同），
// 就算重复：记录、世界状态、规则、道路、角色与物品条目各处都适用。即使两个
// 值相同、交换先后顺序、后一个值让世界合法且按解码结果重算的校验和匹配，
// Latest 与 Record 都必须返回保留记录标识、说明名称重复的 *CorruptError；
// 规则版本不被接受时也先报损坏而不是版本拒绝。
func TestCaseVariantDuplicateFixedFieldCorrupt(t *testing.T) {
	cases := []struct {
		name string
		from string
		to   string
	}{
		// 任务描述的核心情形：先写 "Time": -1，再写 "time": 0/合法值。
		{"时间片大小写后者合法", `"Time": 1,`, `"Time": -1, "time": 1,`},
		// 小写变体在前：交换先后顺序不能让重复通过。
		{"时间片小写变体在前", `"Time": 1,`, `"time": -1, "Time": 1,`},
		// 两个值完全相同也不能通过。
		{"时间片同值大小写", `"Time": 1,`, `"time": 1, "Time": 1,`},
		// 世界状态中的其他固定字段。
		{"种子大小写", `"Seed": 42,`, `"Seed": 7, "seed": 42,`},
		// 规则对象中的固定字段。
