1	package world
2	
3	import (
4		"errors"
5		"reflect"
6		"testing"
7	)
8	
9	// TestCaseVariantDuplicateFixedFieldCorrupt 同一对象内两个名称只要会被
10	// encoding/json 读取为同一个固定字段（仅大小写或 Unicode 转义写法不同），
11	// 就算重复：记录、世界状态、规则、道路、角色与物品条目各处都适用。即使两个
12	// 值相同、交换先后顺序、后一个值让世界合法且按解码结果重算的校验和匹配，
13	// Latest 与 Record 都必须返回保留记录标识、说明名称重复的 *CorruptError；
14	// 规则版本不被接受时也先报损坏而不是版本拒绝。
15	func TestCaseVariantDuplicateFixedFieldCorrupt(t *testing.T) {
16		cases := []struct {
17			name string
18			from string
19			to   string
20		}{
21			// 任务描述的核心情形：先写 "Time": -1，再写 "time": 0/合法值。
22			{"时间片大小写后者合法", `"Time": 1,`, `"Time": -1, "time": 1,`},
23			// 小写变体在前：交换先后顺序不能让重复通过。
24			{"时间片小写变体在前", `"Time": 1,`, `"time": -1, "Time": 1,`},
25			// 两个值完全相同也不能通过。
26			{"时间片同值大小写", `"Time": 1,`, `"time": 1, "Time": 1,`},
27			// 世界状态中的其他固定字段。
28			{"种子大小写", `"Seed": 42,`, `"Seed": 7, "seed": 42,`},
29			// 规则对象中的固定字段。
30			{"规则版本大小写", `"Version": "v1",`, `"Version": "v9", "version": "v1",`},
31			// 一个变体用合法 Unicode 转义写出（u0076 还原为小写 v），还原后
32			// 是 "version"，与 Version 读取为同一字段；先写转义、再写直接写法。
33			{"规则版本Unicode转义", `"Version": "v1",`, `"\u0076ersion": "v9", "Version": "v1",`},
34			// 直接写法在前、转义形式在后：交换先后顺序仍算重复。
35			{"规则版本Unicode转义在后", `"Version": "v1",`, `"Version": "v9", "\u0076ersion": "v1",`},
36			// 时间片的小写变体用转义写出（u0074 还原为小写 t），先写负时间片，
37			// 再以转义字段写回合法值，按解码结果重算校验和也不能通过。
38			{"时间片Unicode转义小写", `"Time": 1,`, `"Time": -1, "\u0074ime": 1,`},
39			// 道路条目中的固定字段（前者引用未知地点、后者写回合法值）。
40			{"道路起点大小写", `"From": "hall"`, `"From": "zzz", "from": "hall"`},
41			{"道路终点大小写", `"To": "yard"`, `"To": "zzz", "to": "yard"`},
42			// 角色对象中的固定字段。
43			{"角色标识大小写", `"ID": "hero",`, `"ID": "villain", "id": "hero",`},
44			{"角色地点大小写", `"Location": "hall",`, `"Location": "zzz", "location": "hall",`},
45			// 物品条目中的固定字段。
46			{"物品名称大小写", `"Item": "gold",`, `"Item": "key", "item": "gold",`},
47			{"物品数量大小写", `"Count": 1`, `"Count": 9, "count": 1`},
48			// 记录信封：字段有 JSON 标签，匹配按标签大小写不敏感进行。
49			{"信封格式字段大小写", `"format": 1,`, `"format": 1, "Format": 1,`},
50			{"信封首记录标记大小写", `"slotFirst": false,`, `"slotFirst": false, "SlotFirst": false,`},
51		}
52		for _, tc := range cases {
53			t.Run(tc.name, func(t *testing.T) {
54				a, _ := newTestArchive(t)
55				ids := saveN(t, a, "s", 1) // r1(time 1) r0(time 0)
56				rewriteRecordText(t, a, ids[0], tc.from, tc.to)
57				before := recordFileBytes(t, a, ids[0])
58	
59				_, err := a.Latest("s", []string{"v1"})
60				assertDuplicateNameCorrupt(t, err, ids[0])
61	
62				_, err = a.Record("s", ids[0], []string{"v1"})
63				assertDuplicateNameCorrupt(t, err, ids[0])
64	
65				// 即使规则版本不被接受，也先报告损坏。
66				_, err = a.Latest("s", []string{"other"})
67				assertDuplicateNameCorrupt(t, err, ids[0])
68	
69				// 只读：文件不被修补，槽指向不变；本槽更早的完好记录仍可读。
70				if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
71					t.Fatal("读取改写了含重复字段的记录")
72				}
73				if p, err := a.readSlotPointerLocked("s"); err != nil || p.Latest != ids[0] {
74					t.Fatalf("槽指向不应改变: %+v err=%v", p, err)
75				}
76				if _, err := a.Record("s", ids[1], []string{"v1"}); err != nil {
77					t.Fatalf("完好的历史记录应可读: %v", err)
78				}
79			})
80		}
81	}
82	
83	// TestCarryLimitKeysCaseSensitive 携带上限解码到 map，键是实际角色标识：
84	// hero 与 HERO 是两个角色，各自的上限与角色条目都必须保留，不能被合并，
85	// 也不能因为大小写不同而误报重复字段。
86	func TestCarryLimitKeysCaseSensitive(t *testing.T) {
87		a, _ := newTestArchive(t)
88		rules := baseRules()
89		rules.CarryLimits = map[string]int{"hero": 5, "HERO": 3}
90		w, err := NewWorld(InitialData{
91			Seed:  42,
92			Rules: rules,
93			Characters: []Character{
94				{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}},
